"use client";

import { useEffect, useRef } from "react";
import { motion, useInView, useMotionValue, useReducedMotion, useSpring, useTransform } from "framer-motion";

function Counter({
  to,
  decimals = 1,
  prefix = "",
  suffix = "",
}: {
  to: number;
  decimals?: number;
  prefix?: string;
  suffix?: string;
}) {
  const ref = useRef(null);
  const isInView = useInView(ref, { once: true, margin: "-10% 0px" });
  const shouldReduceMotion = useReducedMotion();
  const motionValue = useMotionValue(shouldReduceMotion ? to : 0);
  const spring = useSpring(motionValue, { stiffness: 80, damping: 20 });
  const display = useTransform(spring, (v) => `${prefix}${v.toFixed(decimals)}${suffix}`);

  useEffect(() => {
    if (isInView && !shouldReduceMotion) motionValue.set(to);
  }, [isInView, to, motionValue, shouldReduceMotion]);

  return <motion.span ref={ref}>{display}</motion.span>;
}

export function StatCard({
  label,
  value,
  delta,
  sparklinePoints,
}: {
  label: string;
  value: number;
  delta?: number;
  sparklinePoints: string;
}) {
  const shouldReduceMotion = useReducedMotion();

  return (
    <motion.div
      whileHover={shouldReduceMotion ? undefined : { y: -3 }}
      transition={{ type: "spring", stiffness: 400, damping: 28 }}
      className="flex flex-col gap-3 rounded-2xl border border-slate-200 bg-white p-6 transition-shadow duration-300 hover:shadow-lg dark:border-slate-700 dark:bg-neutral-950"
    >
      <span className="text-sm text-slate-500 dark:text-slate-400">{label}</span>
      <div className="flex items-baseline gap-2">
        <span className="text-3xl font-semibold text-slate-900 dark:text-white">
          <Counter to={value} suffix="k" />
        </span>
        {delta !== undefined && (
          <span className="text-sm font-medium text-emerald-700 dark:text-emerald-400">
            <Counter to={delta} prefix="+" suffix="%" />
          </span>
        )}
      </div>
      <svg viewBox="0 0 100 24" className="h-6 w-full text-emerald-500" fill="none" preserveAspectRatio="none">
        <motion.polyline
          points={sparklinePoints}
          stroke="currentColor"
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
          initial={shouldReduceMotion ? { pathLength: 1, opacity: 1 } : { pathLength: 0, opacity: 0 }}
          whileInView={{ pathLength: 1, opacity: 1 }}
          viewport={{ once: true, margin: "-10% 0px" }}
          transition={
            shouldReduceMotion ? { duration: 0 } : { duration: 1, ease: [0.22, 1, 0.36, 1], delay: 0.2 }
          }
        />
      </svg>
    </motion.div>
  );
}
